\version "2.27.2"
% automatically converted by musicxml2ly from 45i-Repeats-Nested.xml
\pointAndClickOff

\header {
  texidoc = "A repeat with two alternative endings. In the first one (enclosing
    bar 2 to bar 4), there is a nested repeat enclosing bar 3. In the second one
    (from bar 5 to bar 6), there is another nested repeat starting also at bar 5
    but ending already at the same bar."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \repeat volta 2 {
    \clef "treble" \time 4/4 \key c \major c1 \alternative {
      \volta 1 {
        | % 1
        c1 \repeat volta 2 {
          | % 2
          c1 }
        | % 3
        c1 }
      \volta 2 {
        \repeat volta 2 {
          | % 4
          c1 }
        | % 5
        c1 }
    }
  }
  | % 6
  c1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
